create table mmse_questions
(
    id                int auto_increment
        primary key,
    section           varchar(20)                            not null comment '所属大项（定向力/记忆力等）',
    question_text     varchar(100)                           not null comment '题目文本',
    question_type     varchar(20)                            not null,
    max_score         int                                    not null comment '本题最高得分',
    position          int                                    not null comment '题号',
    validation_method varchar(20)                            not null comment 'BY_CODE、BY_DATA',
    url_category      varchar(20)                            null,
    url_index         varchar(255)                           null,
    expected_answer   varchar(255) default 'none'            not null,
    create_time       datetime     default CURRENT_TIMESTAMP null,
    update_time       datetime     default CURRENT_TIMESTAMP null,
    constraint mmse_questions_pk
        unique (position)
)
    comment 'MMSE题库';

